Event Type Description <code>ScoreSelected</code> <code>Action&lt;Score&gt;</code> Fired when the player clicks/taps a score row <code>StateChanged</code> <code>Action&lt;BoardViewState&gt;</code> Fired when the component state changes <code>ErrorOccurred</code> <code>Action&lt;LeadrError&gt;</code> Fired when an API error occurs <code>PageLoaded</code> <code>Action&lt;PagedResult&lt;Score&gt;&gt;</code> Fired when a page of scores is successfully loaded <p>Responding to events:</p> <pre><code>public class LeaderboardController : MonoBehaviour
{
    [SerializeField] private LeadrBoardView boardView;

    void OnEnable()
    {
        boardView.ScoreSelected += OnScoreSelected;
        boardView.ErrorOccurred += OnError;
    }

    void OnDisable()
    {
        boardView.ScoreSelected -= OnScoreSelected;
        boardView.ErrorOccurred -= OnError;
    }

    private void OnScoreSelected(Score score)
    {
        Debug.Log($"Player selected: {score.PlayerName}");
    }

    private void OnError(LeadrError error)
    {
        ShowErrorDialog(error.Message);
    }
}
</code></pre>

Event Type Description <code>ScoreSubmitted</code> <code>Action&lt;Score&gt;</code> Fired when the score is successfully submitted. Contains the rank <code>SubmissionFailed</code> <code>Action&lt;LeadrError&gt;</code> Fired when submission fails <code>StateChanged</code> <code>Action&lt;SubmitterState&gt;</code> Fired when the form state changes <code>ValidationChanged</code> <code>Action&lt;bool&gt;</code> Fired when form validity changes (e.g., name meets length requirements) <p>Setting the score programmatically (the typical workflow):</p> <pre><code>public class GameOverController : MonoBehaviour
{
    [SerializeField] private LeadrScoreSubmitter submitter;

    void OnEnable()
    {
        submitter.ScoreSubmitted += OnScoreSubmitted;
        submitter.SubmissionFailed += OnSubmissionFailed;
    }

    void OnDisable()
    {
        submitter.ScoreSubmitted -= OnScoreSubmitted;
        submitter.SubmissionFailed -= OnSubmissionFailed;
    }

    // Call this when the player finishes the level
    public void ShowGameOver(long finalScore)
    {
        submitter.SetScore(finalScore, FormatScore(finalScore));
        gameOverPanel.SetActive(true);
    }

    private void OnScoreSubmitted(Score score)
    {
        Debug.Log($"Submitted! Rank: #{score.Rank}");
        ShowLeaderboardWithHighlight(score.Id);
    }

    private void OnSubmissionFailed(LeadrError error)
    {
        ShowErrorDialog($"Could not submit score: {error.Message}");
    }
}
</code></pre> <p>Need Help? The LEADR team and community is always happy to help on the LEADR Discord</p>
